220	                    functionInstanceStatsData.setSystemExceptionsTotal(metricsData.getSystemExceptionsTotal());
221	                    functionInstanceStatsData.setUserExceptionsTotal(metricsData.getUserExceptionsTotal());
222	                    functionInstanceStatsData.setAvgProcessLatency(metricsData.getAvgProcessLatency());
223	                    functionInstanceStatsData.setLastInvocation(metricsData.getLastInvocation());
224	
