227	                    functionInstanceStatsData.oneMin.setSystemExceptionsTotal(metricsData.getSystemExceptionsTotal1Min());
228	                    functionInstanceStatsData.oneMin.setUserExceptionsTotal(metricsData.getUserExceptionsTotal1Min());
229	                    functionInstanceStatsData.oneMin.setAvgProcessLatency(metricsData.getAvgProcessLatency1Min());
230	
231	                    // Filter out values that are NaN
232	                    Map<String, Double> statsDataMap = metricsData.getUserMetricsMap().entrySet().stream()
233	                            .filter(stringDoubleEntry -> !stringDoubleEntry.getValue().isNaN())
234	                            .collect(Collectors.toMap(x -> x.getKey(), x -> x.getValue()));
235	
236	                    functionInstanceStatsData.setUserMetrics(statsDataMap);
